runs.final_cypher:
MATCH (m:Movie)
WHERE EXISTS { MATCH (m)-[:directedBy]->(:Person {name:'Brad Bird'}) }
OR EXISTS { MATCH (m)-[:releasedIn]->(:Country {name:'United States of America'}) }
RETURN m.name AS name

